package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid" // Will be updated to latest version later
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService defines the interface for user-related business logic
type UserService interface {
	GetAllUsers() []User
	CreateUser(user User) (User, error)
	GetUserByID(id string) (User, error)
}

type userService struct {
	users  map[string]User
	mutex  sync.RWMutex
	// nextID is removed as we will use UUIDs
}

// NewUserService creates and returns a new UserService
func NewUserService() UserService {
	return &userService{
		users: make(map[string]User),
	}
}

func (s *userService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

func (s *userService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	// Generate a new UUID for the user ID
	user.ID = uuid.New().String()
	s.users[user.ID] = user
	return user, nil
}

func (s *userService) GetUserByID(id string) (User, error) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	if !ok {
		return User{}, fmt.Errorf("user with ID %s not found", id)
	}
	return u, nil
}

package api

import (
	"encoding/json"
	"net/http"

	"./../service" // Relative import for the service package
)

// UserHandler handles HTTP requests for user-related operations
type UserHandler struct {
	service service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(s service.UserService) *UserHandler {
	return &UserHandler{
		service: s,
	}
}

// RegisterRoutes registers the user API routes
func (h *UserHandler) RegisterRoutes() {
	http.HandleFunc("/users", h.handleUsers)
	http.HandleFunc("/users/", h.handleUserByID)
}

func (h *UserHandler) handleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetAllUsersHandler(w, r)
	case http.MethodPost:
		h.CreateUserHandler(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandler) handleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]

	switch r.Method {
	case http.MethodGet:
		h.GetUserByIDHandler(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetAllUsersHandler handles GET requests for all users
func (h *UserHandler) GetAllUsersHandler(w http.ResponseWriter, r *http.Request) {
	users := h.service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUserHandler handles POST requests to create a new user
func (h *UserHandler) CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.service.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError) // Or appropriate error
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByIDHandler handles GET requests for a single user by ID
func (h *UserHandler) GetUserByIDHandler(w http.ResponseWriter, r *http.Request, id string) {
	user, err := h.service.GetUserByID(id)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

